WITH base AS (SELECT *, FLOOR(discount_pct) AS discount_pct_whole FROM promotions WHERE discount_pct >= 0.12 AND channel IS NOT NULL), metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel, promo_code ORDER BY discount_pct, id) AS row_seq, SUM(discount_pct_whole) OVER (PARTITION BY channel, promo_code) AS channel_sum_discount_pct_whole, ROW_NUMBER() OVER (PARTITION BY channel, promo_code ORDER BY discount_pct DESC, id) AS event_seq, LEAD(discount_pct_whole, 1) OVER (PARTITION BY channel, promo_code ORDER BY discount_pct, id) AS next_discount_pct_whole FROM base WHERE discount_pct >= 0.25), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel, promo_code ORDER BY ends_on DESC, id) AS rank_in_group FROM metrics QUALIFY rank_in_group = 1), with_window AS (SELECT src.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM latest src LEFT JOIN promotions pr ON src.channel <=> pr.channel AND src.starts_on >= pr.starts_on AND src.starts_on <= DATE_ADD(pr.ends_on, 10)) SELECT promo_id, SIZE(COLLECT_SET(channel)) AS num_channels, ROUND(SUM(channel_sum_discount_pct_whole) / NULLIF(COUNT(CASE WHEN promo_code = 'SPRING10' THEN 1 END), 0), 2) AS channel_sum_discount_pct_whole_per_spring10, COUNT(*) AS cnt, SIZE(COLLECT_SET(channel)) AS num_channels_2, COUNT_IF(promo_code = 'SPRING10') AS spring10_events, COUNT(*) AS row_count FROM with_window GROUP BY 1 ORDER BY num_channels_2 DESC NULLS FIRST
